/* ---------- QR (decorative, deterministic) ---------- */
(function(){
  const c = $('#qr'), x = c.getContext('2d'), n = 25, s = c.width / n; let seed = 7;
  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height); x.fillStyle = '#1B1030';
  const finder = (cx, cy) => { x.fillRect(cx*s, cy*s, 7*s, 7*s); x.fillStyle = '#fff'; x.fillRect((cx+1)*s, (cy+1)*s, 5*s, 5*s); x.fillStyle = '#1B1030'; x.fillRect((cx+2)*s, (cy+2)*s, 3*s, 3*s); };
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) { const inF = (i < 8 && j < 8) || (i > n-9 && j < 8) || (i < 8 && j > n-9); if (!inF && rnd() > .52) x.fillRect(i*s, j*s, s, s); }
  finder(0, 0); finder(n-7, 0); finder(0, n-7);
  x.fillStyle = '#FF9A3C'; x.beginPath(); x.arc(c.width/2, c.height/2, 11, 0, 7); x.fill();
})();

/* ---------- Mere Niyam: rule board + knock simulator (same order of checks as the app) ---------- */
const KINDS = [['message','Message'],['voice_note','Voice note'],['file','File / photo'],['app_file','App file'],['email','Email'],['link','Link'],['presentation','Presentation'],['meeting','Meeting'],['payment_request','Payment request'],['contact_card','Contact card'],['location','Location']];
const ACCEPT = {message:'ask',voice_note:'ask',file:'ask',app_file:'ask',email:'ask',link:'ask',presentation:'ask',meeting:'ask',payment_request:'ask',contact_card:'ask',location:'never'};
const LOCKED = new Set(['payment_request','app_file']);
const CYCLE = {ask:'auto', auto:'never', never:'ask'};
const SIMK = ['message','file','meeting','payment_request','location'];
const sim = {who:'family', kind:'message', topic:'', time:'day'};
function drawKinds() {
  $('#kinds').innerHTML = KINDS.map(([k, n]) => `<button type="button" class="kind${LOCKED.has(k) ? ' lock' : ''}" data-k="${k}" data-v="${ACCEPT[k]}" aria-label="${esc(n)}: ${ACCEPT[k]}${LOCKED.has(k) ? ', always asks' : ''}">${esc(n)}<em>${ACCEPT[k]}</em></button>`).join('');
}
drawKinds();
$('#kinds').addEventListener('click', e => { const b = e.target.closest('.kind'); if (!b) return; const k = b.dataset.k;
  if (LOCKED.has(k)) { if (window.gsap) gsap.fromTo(b, {x:-6}, {x:0, duration:.4, ease:'elastic.out(1,.3)'}); return; }
  ACCEPT[k] = CYCLE[ACCEPT[k]]; drawKinds(); decide(); });
$('#sKind').innerHTML = SIMK.map((k, i) => `<button type="button" data-v="${k}" aria-pressed="${i === 0}">${esc(KINDS.find(x => x[0] === k)[1])}</button>`).join('');
['sWho','sKind','sTopic','sTime'].forEach(id => $('#' + id).addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return;
  [...b.parentElement.children].forEach(x => x.setAttribute('aria-pressed', x === b)); sim[{sWho:'who',sKind:'kind',sTopic:'topic',sTime:'time'}[id]] = b.dataset.v; decide(); }));
function decide() {
  const vip = sim.who === 'family', quiet = sim.time === 'night', k = sim.kind; let act, why, color;
  if (sim.who === 'stranger') { act = 'Connect request only'; why = 'Aap jude nahi ho. Unhe aapka Hoola ID ya QR chahiye, aur sirf aapki Haan se judenge. Tab tak koi message andar nahi aata.'; color = 'var(--faint)'; }
  else if (sim.topic && !vip) { act = 'Mana (declined)'; why = `'${sim.topic}' wali baatein aapne mana ki hain. Unki Hoola ko vinamrata se mana kar diya.`; color = 'var(--bad)'; }
  else if (ACCEPT[k] === 'never' && !(vip && (k === 'message' || k === 'voice_note'))) { act = 'Mana (declined)'; why = 'Aapke niyam mein yeh mana hai.'; color = 'var(--bad)'; }
  else if (LOCKED.has(k)) { act = 'Aapse poochhega'; why = 'Paise aur app files hamesha aapse poochh kar. Yeh niyam badla nahi ja sakta.'; color = 'var(--saffron)'; }
  else if (k === 'file' && vip) { act = 'Seedha le liya'; why = 'VIP ki file: aapke niyam kehte hain le lo. Phir bhi pehle quarantine mein jaanchi gayi.'; color = 'var(--ok)'; }
  else if (ACCEPT[k] === 'auto') { act = 'Seedha le liya'; why = 'Aapke niyam: seedha le lo.'; color = 'var(--ok)'; }
  else { act = 'Aapse poochhega'; why = 'Card aayega: Haan, Mana, Baad mein ya Tum sambhalo.'; color = 'var(--saffron)'; }
  if (vip && sim.topic && sim.who !== 'stranger' && act !== 'Mana (declined)') why += ' (VIP hai, isliye mana kiye vishay ka niyam nahi laga.)';
  const q = sim.who !== 'stranger' && quiet && act !== 'Mana (declined)' ? (vip ? 'Quiet hours, par VIP ring kar sakte hain: abhi bataya.' : 'Quiet hours (10 pm to 8 am): chupchaap rakha, subah 8 baje batayega.') : '';
  const v = $('#verdict'); v.querySelector('.act').textContent = act; v.querySelector('.act').style.color = color; v.querySelector('.why').textContent = why; v.querySelector('.quiet').textContent = q;
  if (window.gsap && !reduce) gsap.fromTo(v, {y:8, opacity:.4}, {y:0, opacity:1, duration:.35, ease:'power2.out'});
}
decide();

