function hub(id, kind) {
  const s = $('#' + id), cx = 160, cy = 120, R = 82, n = 6, nodes = [];
  for (let i = 0; i < n; i++) { const a = -Math.PI/2 + i * 2*Math.PI/n, x = cx + R*Math.cos(a), y = cy + R*Math.sin(a);
    svgEl('line', {x1:cx, y1:cy, x2:x, y2:y, stroke:'rgba(255,255,255,.12)', 'stroke-width':2}, s); nodes.push([x, y]); }
  nodes.forEach(([x, y], i) => { svgEl('circle', {cx:x, cy:y, r:15, fill:'#2a2050', stroke:'#7C5CFF', 'stroke-width':2}, s);
    svgEl('clipPath', {id:id+'c'+i}, s).appendChild(svgEl('circle', {cx:x, cy:y, r:13}));
    svgEl('image', {href:FACES[i % FACES.length], x:x-13, y:y-13, width:26, height:26, 'clip-path':`url(#${id}c${i})`, preserveAspectRatio:'xMidYMin slice'}, s); });
  svgEl('circle', {cx:cx, cy:cy, r:26, fill:'#FFB15C'}, s);
  const t = svgEl('text', {x:cx, y:cy+5, 'text-anchor':'middle', fill:'#1B1030', 'font-size':13, 'font-weight':800, 'font-family':'Sora,sans-serif'}, s); t.textContent = kind === 'C' ? 'filter' : 'hub';
  const dots = nodes.map(() => svgEl('circle', {cx:cx, cy:cy, r:6, fill: kind === 'B' ? '#F87171' : (kind === 'C' ? '#34D399' : '#FFB15C'), opacity:0}, s));
  return {cx, cy, nodes, dots};
}
