/* ---------- night sky ---------- */
(function(){
  const c = $('#sky'), x = c.getContext('2d'); let W, H, stars;
  const L = [{c:'255,154,60',r:.55,x:.2,y:.25,p:0},{c:'192,85,245',r:.6,x:.82,y:.4,p:2},{c:'124,92,255',r:.7,x:.5,y:.9,p:4}];
  const size = () => { W = c.width = Math.round(innerWidth * .5); H = c.height = Math.round(innerHeight * .5); stars = Array.from({length: Math.round(W * H / 1500)}, () => ({x: Math.random() * W, y: Math.random() * H, r: Math.random() * .9 + .2, t: Math.random() * 6})); };
  const draw = t => { const sp = scrollY / Math.max(1, document.documentElement.scrollHeight - innerHeight);
    x.fillStyle = '#0B0A1A'; x.fillRect(0, 0, W, H); x.globalCompositeOperation = 'lighter';
    L.forEach(l => { const px = (l.x + Math.sin(t * .0001 + l.p) * .12) * W, py = (l.y + Math.cos(t * .00008 + l.p) * .1 - sp * .3) * H, R = l.r * Math.max(W, H), g = x.createRadialGradient(px, py, 0, px, py, R); g.addColorStop(0, `rgba(${l.c},.18)`); g.addColorStop(1, `rgba(${l.c},0)`); x.fillStyle = g; x.fillRect(0, 0, W, H); });
    x.globalCompositeOperation = 'source-over';
    stars.forEach(s => { x.fillStyle = `rgba(244,242,255,${.6 * (.4 + .4 * Math.sin(t * .0012 + s.t))})`; x.fillRect(s.x, ((s.y - sp * 60) % H + H) % H, s.r, s.r); }); };
  size(); addEventListener('resize', size);
  if (reduce) { draw(0); return; }
  let vis = true; document.addEventListener('visibilitychange', () => vis = !document.hidden);
  (function loop(t){ if (vis) draw(t); requestAnimationFrame(loop); })(0);
})();

